"""Write benchmark/questions.jsonl (split fixed here, before any experiment). Run: python3 -I benchmark/build_questions.py"""
import json
from pathlib import Path
A, B = "nist-ai-100-1", "nist-ai-600-1"
# (id, split, type, question, answer, doc, page, quote, filter)
Q = [
 ("q01","dev","direct","Does the AI RMF prescribe a risk tolerance?","No; it can be used to prioritize risk but does not prescribe risk tolerance.",A,12,"While the AI RMF can be used to prioritize risk, it does not prescribe risk tolerance.",None),
 ("q02","dev","direct","How does the AI RMF, citing ISO/IEC TS 5723:2022, define accuracy?","Closeness of results of observations, computations, or estimates to the true values or the values accepted as being true.",A,19,"“closeness of results of observations, computations, or estimates to the true values or the values accepted as being true.”",None),
 ("q03","dev","paraphrase","How is resilience different from security for an AI system?","Resilience is returning to normal function after an adverse event; security includes resilience plus protocols to avoid, protect against, respond to, or recover from attacks.",A,20,"While resilience is the ability to return to normal function after an unexpected adverse event, security includes resilience but also encompasses protocols to avoid, protect against, respond to, or recover from attacks.",None),
 ("q04","dev","direct","Which question does each of transparency, explainability and interpretability answer?","Transparency: what happened; explainability: how a decision was made; interpretability: why it was made and its meaning/context to the user.",A,22,"Transparency can answer the question of “what happened” in the system. Explainability can answer the question of “how” a decision was made in the system. Interpretability can answer the question of “why” a decision was made by the system and its meaning or context to the user.",None),
 ("q05","dev","condition","If a system has mitigated harmful bias, can we conclude it is fair?","No; systems in which harmful biases are mitigated are not necessarily fair.",A,22,"Systems in which harmful biases are mitigated are not necessarily fair.",None),
 ("q06","dev","paraphrase","Which AI RMF function runs through the whole risk management process and enables the other functions?","GOVERN.",A,27,"GOVERN is a cross-cutting function that is infused throughout AI risk management and enables the other functions of the process.",None),
 ("q07","dev","metadata_filter","Which subcategory requires that risks or trustworthiness characteristics that will not or cannot be measured are documented?","MEASURE 1.1",A,34,"The risks or trustworthiness characteristics that will not – or cannot – be measured are properly documented.",{"document_id":A}),
 ("q08","dev","direct","Why do generative models produce confabulations?","They generate outputs that approximate the statistical distribution of their training data, e.g. LLMs predict the next token.",B,10,"Confabulations are a natural result of the way generative models are designed: they generate outputs that approximate the statistical distribution of their training data",None),
 ("q09","dev","paraphrase","What other terms are used colloquially for confabulation?","Hallucinations or fabrications.",B,10,"These phenomena are colloquially also referred to as “hallucinations” or “fabrications.”",None),
 ("q10","dev","direct","What is jailbreaking?","Deliberately crafting prompts to manipulate them and circumvent output controls.",B,11,"Crafting such prompts deliberately is known as “jailbreaking,” or, manipulating prompts to circumvent output controls.",None),
 ("q11","dev","direct","Is there an agreed method to estimate the environmental impacts of generative AI?","No; there is currently no agreed upon method.",B,12,"Currently there is no agreed upon method to estimate environmental impacts from GAI.",None),
 ("q12","dev","direct","What is model collapse?","Training that over-relies on synthetic data, so data points disappear from the new model's output distribution.",B,13,"Model collapse can occur when model training over-relies on synthetic data, resulting in data points disappearing from the distribution of the new model’s outputs.",None),
 ("q13","dev","paraphrase","What is the term for excessive deference to automated systems?","Automation bias.",B,13,"This phenomenon is an example of automation bias, or excessive deference to automated systems.",None),
 ("q14","dev","metadata_filter","Which suggested action says to compare GAI outputs against pre-defined risk tolerance, guidelines and principles?","MG-2.2-001 (MANAGE 2.2)",B,44,"Compare GAI system outputs against pre-defined organization risk tolerance, guidelines, and principles, and review and test AI-generated content against these guidelines.",{"document_id":B,"function":"MANAGE"}),
 ("q15","dev","condition","Why might testing GAI with human standardized exams not be enough before deployment?","Such anecdotal testing does not guarantee validity or reliability in those domains.",B,53,"does not guarantee GAI system validity or reliability in those domains.",None),
 ("q16","test","direct","What does the AI RMF say about trying to eliminate negative risk entirely?","It can be counterproductive because not all incidents and failures can be eliminated.",A,12,"Attempting to eliminate negative risk entirely can be counterproductive in practice because not all incidents and failures can be eliminated.",None),
 ("q17","test","metadata_filter","Which security concerns are commonly raised for AI systems?","Adversarial examples, data poisoning, and exfiltration of models, training data or other IP through endpoints.",A,20,"Common security concerns relate to adversarial examples, data poisoning, and the exfiltration of models, training data, or other intellectual property through AI system endpoints.",{"document_id":A}),
 ("q18","test","paraphrase","Which suggested action tells teams to regularly check GAI systems for ways safety measures can be circumvented?","MS-2.6-007 (MEASURE 2.6)",B,36,"Regularly evaluate GAI system vulnerabilities to possible circumvention of safety",None),
 ("q19","test","direct","What is AI red-teaming?","A structured testing exercise to probe an AI system for flaws and vulnerabilities such as inaccurate, harmful or discriminatory outputs.",B,53,"AI Red-teaming: A structured testing exercise used to probe an AI system to find flaws and vulnerabilities such as inaccurate, harmful, or discriminatory outputs",None),
 ("q20","test","direct","What is data memorization in LLMs?","LLMs revealing sensitive training data (even from the public domain) during adversarial attacks.",B,11,"This problem has been referred to as data memorization",None),
]
out = Path(__file__).parent / "questions.jsonl"
with out.open("w") as f:
    for i, s, t, q, a, d, p, e, flt in Q:
        r = dict(id=i, split=s, type=t, question=q, expected_answer=a, gold_source_id=d, gold_page=p, evidence_quote=e)
        if flt: r["filter"] = flt
        f.write(json.dumps(r, ensure_ascii=False) + "\n")
